before.content:
$target = $configuration["JI_TEST_SSH_TARGET"]
$key = [REDACTED_CREDENTIAL]"JI_TEST_SSH_KEY"]
$origin = $configuration["JI_TEST_RELAY_ORIGIN"]
if ([string]::IsNullOrWhiteSpace($target) -or [string]::IsNullOrWhiteSpace($key)) {
    throw "JI_TEST_SSH_TARGET and JI_TEST_SSH_KEY are required"
}

after.content:
rm -f "`$root/source.tar.gz"
"@
    & "$PSScriptRoot\run-stage5-remote-topology.ps1" -Target $target -IdentityFile $key `
        -RelayOrigin $origin -EvidenceDirectory $env:JI_STAGE5_EVIDENCE_DIR
    if (-not $?) { throw "Stage 5 Remote Host topology failed" }
} finally {
    if (Test-Path -LiteralPath $archive) { Remove-Item -LiteralPath $archive -Force }
